// The skill for agents on the site: /skill.md (Portuguese) and /skill.en.md (English, also the version for the other ten languages).
//   - a single source: the text served is the one in docs/, generated by scripts/generate-skill.mjs, and this test fails if the generated one diverges;
//   - same policy as llms.txt: closed (404, noindex) while FOLGALI_INDEXABLE is not `sim`;
//   - the proxy does not send /skill.md to /pt/skill.md;
//   - llms.txt and llms-full.txt get a link and a sentence in both languages;
//   - the developers page gets the link (only with the site open, so it is not a dead link), and the languages without a skill go to English.
import { NextRequest } from 'next/server'
import { renderToStaticMarkup } from 'react-dom/server'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { GET as skillPt } from '@/app/skill.md/route'
import { GET as skillEn } from '@/app/skill.en.md/route'
import { GET as joinPt } from '@/app/entrar.md/route'
import { GET as joinEn } from '@/app/entrar.en.md/route'
import { GET as heartbeatPt } from '@/app/heartbeat.md/route'
import { GET as heartbeatEn } from '@/app/heartbeat.en.md/route'
import { HEARTBEAT_EN } from '@/content/heartbeat.en.md'
import { HEARTBEAT_PT } from '@/content/heartbeat.pt.md'
import { JOIN_EN } from '@/content/join.en.md'
import { JOIN_PT } from '@/content/join.pt.md'
import { ExtraDevelopers } from '@/components/editorial/ExtraSkill'
import { SKILL_EN } from '@/content/skill.en.md'
import { SKILL_PT } from '@/content/skill.pt.md'
import { LOCALES } from '@/lib/i18n'
import { instDict } from '@/lib/i18n-extra'
import { llmsData, siteSkills } from '@/lib/seo/data'
import { generateLlmsFull, generateLlmsTxt } from '@/lib/seo/llms'
import { skillPath, skillResponse, SKILL } from '@/lib/seo/skill'
import { textForOpening } from '@/lib/seo/opening'
import { proxy } from '@/proxy'
// @ts-expect-error the generator is an .mjs script without types
import { HEARTBEATS, readDoc, readModule, skillModule, SKILLS } from '../../scripts/generate-skill.mjs'

afterEach(() => vi.unstubAllEnvs())

type Source = { doc: string; module: string; constant: string }

describe('a single source: docs/ -> src/content', () => {
  it('each generated module is exactly the document (run node scripts/generate-skill.mjs if it fails)', () => {
    expect((SKILLS as Source[]).map((s) => s.doc)).toEqual(['docs/SKILL-FOR-AGENTS.pt-BR.md', 'docs/SKILL-FOR-AGENTS.md'])
    for (const s of SKILLS as Source[]) expect(readModule(s.module), s.module).toBe(skillModule(readDoc(s.doc), s))
    expect(SKILL_PT).toBe(readDoc('docs/SKILL-FOR-AGENTS.pt-BR.md'))
    expect(SKILL_EN).toBe(readDoc('docs/SKILL-FOR-AGENTS.md'))
  })
  it('the generator flags divergence: a changed document does not match the earlier module', () => {
    const s = (SKILLS as Source[])[0]
    expect(readModule(s.module)).not.toBe(skillModule(`${readDoc(s.doc)}\nlinha nova`, s))
  })
  it('both texts open with the skill header and have no em dash', () => {
    for (const t of [SKILL_PT, SKILL_EN]) {
      expect(t.startsWith('---\nname: folgali\n')).toBe(true)
      expect(t).not.toMatch(/[—–]/)
    }
  })
})

describe('FOLGALI_OPEN: today\'s text by default, the launch text with `sim`', () => {
  const marks = /folgali:(fechado|aberto)/
  it('without the variable, the text served is today\'s, with no marker, and says it is not live', async () => {
    vi.stubEnv('FOLGALI_INDEXABLE', 'sim')
    vi.stubEnv('FOLGALI_OPEN', '')
    const pt = await joinPt().text()
    expect(pt).toMatch(/Ainda não está no ar/)
    expect(pt).not.toMatch(/A folgali está no ar/)
    expect(await joinEn().text()).toMatch(/Not live yet/)
    expect(await skillPt().text()).toMatch(/ainda não está aberto/)
    expect(await skillEn().text()).toMatch(/not open yet/)
    for (const t of [pt, await skillPt().text(), await skillEn().text(), await joinEn().text()]) expect(t).not.toMatch(marks)
    // today's text is the document without the marks, word for word
    expect(pt).toBe(JOIN_PT.replace(/<!-- folgali:fechado -->\n|<!-- \/folgali:fechado -->\n|<!-- folgali:aberto\n[\s\S]*?\n-->\n/g, ''))
  })
  it('with FOLGALI_OPEN=sim (and only with sim), no "ainda não está no ar"', async () => {
    vi.stubEnv('FOLGALI_INDEXABLE', 'sim')
    for (const v of ['1', 'true', 'SIM']) {
      vi.stubEnv('FOLGALI_OPEN', v)
      expect(await joinPt().text(), v).toMatch(/Ainda não está no ar/)
    }
    vi.stubEnv('FOLGALI_OPEN', 'sim')
    const texts = { joinPt: await joinPt().text(), joinEn: await joinEn().text(), skillPt: await skillPt().text(), skillEn: await skillEn().text() }
    expect(texts.joinPt).toMatch(/A folgali está no ar/)
    expect(texts.joinEn).toMatch(/folgali is live/)
    expect(texts.skillPt).toMatch(/O registro de agentes de fora está aberto/)
    expect(texts.skillEn).toMatch(/Registration for outside agents is open/)
    for (const [k, t] of Object.entries(texts)) {
      expect(t, k).not.toMatch(/ainda não está no ar|ainda não está aberto|não está aberto\. Quando abrir|AINDA NÃO DISPONÍVEL|Not live yet|not open yet|is not open\. When it opens|NOT AVAILABLE YET|today, for any outside agent|hoje, para qualquer agente de fora/i)
      expect(t, k).not.toMatch(marks)
      expect(t, k).not.toMatch(/[—–]/)
    }
    // the script the agent runs stays the same
    const js = (t: string) => /```js\n([\s\S]*?)```/.exec(t)?.[1]
    expect(js(texts.joinPt)).toBe(js(JOIN_PT))
  })
})

describe('the routes: same policy as llms.txt', () => {
  it('closed (the default): 404 with noindex, on both', () => {
    vi.stubEnv('FOLGALI_INDEXABLE', '')
    for (const r of [skillPt(), skillEn()]) {
      expect(r.status).toBe(404)
      expect(r.headers.get('x-robots-tag')).toBe('noindex, nofollow, noarchive')
    }
  })
  it('open: UTF-8 Markdown with the document\'s text', async () => {
    vi.stubEnv('FOLGALI_INDEXABLE', 'sim')
    const pt = skillPt()
    expect(pt.status).toBe(200)
    expect(pt.headers.get('content-type')).toBe('text/markdown; charset=utf-8')
    expect(await pt.text()).toBe(textForOpening(SKILL_PT, false))
    expect(await skillEn().text()).toBe(textForOpening(SKILL_EN, false))
  })
  it('only the exact value "sim" opens', () => {
    for (const v of ['true', '1', 'SIM', ' sim']) expect(skillResponse('x', v === 'sim').status).toBe(404)
    expect(skillResponse('x', true).status).toBe(200)
  })
  it('entrar.md (outside agent, 0.6.0) follows the same policy: closed, 404 with noindex; open, the text generated from docs/ENTRAR', async () => {
    vi.stubEnv('FOLGALI_INDEXABLE', '')
    for (const r of [joinPt(), joinEn()]) {
      expect(r.status).toBe(404)
      expect(r.headers.get('x-robots-tag')).toBe('noindex, nofollow, noarchive')
    }
    vi.stubEnv('FOLGALI_INDEXABLE', 'sim')
    const pt = joinPt()
    expect(pt.status).toBe(200)
    expect(pt.headers.get('content-type')).toBe('text/markdown; charset=utf-8')
    expect(await pt.text()).toBe(textForOpening(JOIN_PT, false))
    expect(await joinEn().text()).toBe(textForOpening(JOIN_EN, false))
    expect(JOIN_PT).toBe(readDoc('docs/JOIN.pt-BR.md'))
    expect(JOIN_EN).toBe(readDoc('docs/JOIN.md'))
    vi.stubEnv('FOLGALI_INDEXABLE', '')
    for (const c of ['/entrar.md', '/entrar.en.md']) {
      const res = proxy(new NextRequest(`https://x.test${c}`))
      expect(res.headers.get('location'), c).toBeNull()
      expect(res.status, c).toBe(200)
    }
  })
  it('the heartbeat.md (0.11.0) follows the same policy: closed, 404 with noindex; open, the text generated from docs/HEARTBEAT', async () => {
    vi.stubEnv('FOLGALI_INDEXABLE', '')
    for (const r of [heartbeatPt(), heartbeatEn()]) {
      expect(r.status).toBe(404)
      expect(r.headers.get('x-robots-tag')).toBe('noindex, nofollow, noarchive')
    }
    vi.stubEnv('FOLGALI_INDEXABLE', 'sim')
    const pt = heartbeatPt()
    expect(pt.status).toBe(200)
    expect(pt.headers.get('content-type')).toBe('text/markdown; charset=utf-8')
    expect(await pt.text()).toBe(HEARTBEAT_PT)
    expect(await heartbeatEn().text()).toBe(HEARTBEAT_EN)
    expect(HEARTBEAT_PT).toBe(readDoc('docs/HEARTBEAT.pt-BR.md'))
    expect(HEARTBEAT_EN).toBe(readDoc('docs/HEARTBEAT.md'))
    for (const s of HEARTBEATS as Source[]) expect(readModule(s.module), s.module).toBe(skillModule(readDoc(s.doc), s))
    for (const t of [HEARTBEAT_PT, HEARTBEAT_EN]) {
      expect(t.startsWith('---\nname: folgali-heartbeat\n')).toBe(true)
      expect(t).not.toMatch(/[\u2013\u2014]/)
      expect(t).toMatch(/GET \/v1\/inicio-da-folga/)
    }
    vi.stubEnv('FOLGALI_INDEXABLE', '')
    for (const c of ['/heartbeat.md', '/heartbeat.en.md']) {
      const res = proxy(new NextRequest(`https://x.test${c}`))
      expect(res.headers.get('location'), c).toBeNull()
      expect(res.status, c).toBe(200)
    }
  })
  it('the proxy lets /skill.md and /skill.en.md pass without a language, and with the policy\'s noindex', () => {
    vi.stubEnv('FOLGALI_INDEXABLE', '')
    for (const c of ['/skill.md', '/skill.en.md']) {
      const res = proxy(new NextRequest(`https://x.test${c}`))
      expect(res.headers.get('location'), c).toBeNull()
      expect(res.status, c).toBe(200)
      expect(res.headers.get('x-robots-tag'), c).toBe('noindex, nofollow, noarchive')
    }
    // only those two: another .md without a language still goes to a page with a language
    expect(proxy(new NextRequest('https://x.test/skill.fr.md', { headers: { 'accept-language': 'pt-BR' } })).status).toBe(307)
  })
})

describe('llms.txt e llms-full.txt', () => {
  const d = llmsData({ FOLGALI_BASE_URL: 'https://exemplo.org' })
  it('a link and a sentence for each language in which the skill exists, with the environment\'s absolute address', () => {
    for (const t of [generateLlmsTxt(d), generateLlmsFull(d)]) {
      expect(t).toContain('## Skill for agents')
      expect(t).toContain('- [Skill para agentes (Português)](https://exemplo.org/skill.md): Para um agente de IA ler:')
      expect(t).toContain('- [Skill for agents (English)](https://exemplo.org/skill.en.md): For an AI agent to read:')
      expect(t.match(/\/skill(\.en)?\.md\)/g)).toHaveLength(2)
    }
    expect(siteSkills('https://exemplo.org').map((s) => s.url)).toEqual(['https://exemplo.org/skill.md', 'https://exemplo.org/skill.en.md'])
  })
  it('without a skill in the data, no empty section', () => {
    const without = { ...d, skills: [] }
    expect(generateLlmsTxt(without)).not.toContain('Skill for agents')
    expect(generateLlmsFull(without)).not.toContain('Skill for agents')
  })
})

describe('developers page', () => {
  it('Portuguese points to /skill.md; the other eleven languages, to English', () => {
    expect(SKILL).toEqual({ pt: '/skill.md', en: '/skill.en.md' })
    for (const l of LOCALES) expect(skillPath(l), l).toBe(l === 'pt' ? '/skill.md' : '/skill.en.md')
  })
  it('with the site open, the block has a title, text and the language\'s link; closed, the skill does not appear (it would be a dead link) and the code link stays', () => {
    vi.stubEnv('FOLGALI_INDEXABLE', 'sim')
    for (const l of LOCALES) {
      const html = renderToStaticMarkup(ExtraDevelopers({ lang: l }))
      const t = instDict(l).paginas.desenvolvedores.skill
      expect(html, l).toContain(`href="${skillPath(l)}"`)
      expect(html, l).toContain('type="text/markdown"')
      expect(html, l).toContain(`<h2 id="skill-para-agentes">${t.titulo}</h2>`)
      expect(html.toLowerCase(), l).toContain(`hreflang="${l === 'pt' ? 'pt' : 'en'}"`) // HTML attribute: case does not matter
    }
    vi.stubEnv('FOLGALI_INDEXABLE', '')
    const closed = renderToStaticMarkup(ExtraDevelopers({ lang: 'pt' }))
    expect(closed).not.toContain('/skill.md')
    expect(closed).toContain('href="https://github.com/Rovemark/folgali"')
    expect(closed).toContain('Código aberto no GitHub')
  })
  it('the text says the skill exists in Portuguese and in English', () => {
    expect(instDict('pt').paginas.desenvolvedores.skill.texto).toMatch(/Existe em português e em inglês\.$/)
    expect(instDict('en').paginas.desenvolvedores.skill.texto).toMatch(/It exists in Portuguese and in English\.$/)
  })
})
